import { useState, useEffect } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate, Link } from 'react-router-dom'
import { useLanguage } from '../../context/LanguageContext'
import { useAuth } from '../../context/AuthContext'
import { TRIAL_ACTIVE } from '../../config/trial'
import { estaDisponivel } from '../../config/site'
import Farol from '../../components/Farol/Farol'
import CapCard from '../../components/CapCard/CapCard'
import index from '../../data/livro-index.json'
import './Livro.css'
import './Contos.css'

function formatarData(dataStr) {
  if (!dataStr) return ''
  const [a, m, d] = dataStr.split('-')
  return `${d}/${m}/${a}`
}

export default function Livro() {
  const [ultimo, setUltimo] = useState(null)
  const navigate = useNavigate()
  const { locale, t } = useLanguage()
  const { user, perfil } = useAuth()
  const ADMIN_EMAILS = ['isaiasgamedev@gmail.com', 'gramikgames@gmail.com']
  const isAdmin = perfil?.is_admin === true || ADMIN_EMAILS.includes(user?.email || '')

  useEffect(() => {
    setUltimo(localStorage.getItem('ldi-livro-ultimo'))
  }, [])

  const tituloKey = locale === 'en' ? 'titulo_en' : locale === 'es' ? 'titulo_es' : 'titulo'

  return (
    <section className="livro-page">
      <Helmet>
        <title>Book — Illusion Fight</title>
        <meta name="description" content="Read the Illusion Fight book chapters online. The complete novel of the LDI universe — follow Kim, Jack, and the fighters of Bravara." />
        <meta property="og:title" content="Book — Illusion Fight" />
        <meta property="og:description" content="Read the Illusion Fight book online. The complete novel of the LDI universe." />
        <meta property="og:url" content="https://illusionfight.com/historias/lutas-de-ilusao" />
        <meta property="og:image" content="https://illusionfight.com/og-image.jpg" />
        <meta property="og:type" content="website" />
        <link rel="alternate" hrefLang="pt" href="https://illusionfight.com/historias/lutas-de-ilusao" />
        <link rel="alternate" hrefLang="en" href="https://illusionfight.com/historias/lutas-de-ilusao" />
        <link rel="alternate" hrefLang="es" href="https://illusionfight.com/historias/lutas-de-ilusao" />
      </Helmet>
      <div className="container">
        {ultimo && (
          <Link to={`/historias/lutas-de-ilusao/${ultimo}`} className="livro-continuar">
            {t('pages.livro.continuar_lendo')}
          </Link>
        )}
        <nav className="livro-linhas">
          <Link to="/historias" className="livro-linha">{t('pages.historias.titulo')}</Link>
          <span className="livro-linha livro-linha--ativa">{t('pages.contos.linha_principal')}</span>
          <Link to="/historias/contos" className="livro-linha">{t('pages.contos.linha_contos')}</Link>
        </nav>
        <h2 className="section-title">{t('pages.livro.titulo')}</h2>
        <div className="livro-farol">
          <Farol peso="pesada" canon={true} temas={['luta', 'familia', 'amizade', 'crime', 'humor']} />
          <p className="contos-hero__aviso">{t('pages.contos.peso_pesada_desc')}</p>
        </div>
        <div className="cap-list">
          {index.map(ch => {
            const liberado = ch.id === 'capitulo-01' || estaDisponivel(ch, isAdmin, { user, perfil })
            const resumoKey = locale === 'en' ? 'resumo_en' : locale === 'es' ? 'resumo_es' : 'resumo_pt'
            const taglineKey = locale === 'en' ? 'tagline_en' : locale === 'es' ? 'tagline_es' : 'tagline_pt'
            return (
              <CapCard
                key={ch.id}
                to={`/historias/lutas-de-ilusao/${ch.id}`}
                liberado={liberado}
                releaseItem={ch}
                rotulo={`${t('pages.livro.cap')} ${String(ch.numero).padStart(2, '0')}`}
                titulo={ch[tituloKey]}
                resumo={ch[resumoKey] || ch[taglineKey] || ''}
                meta={liberado && ch.data_publicacao ? formatarData(ch.data_publicacao) : ''}
                badge={ch.data_publicacao ? `${t('pages.livro.em_breve')} — ${formatarData(ch.data_publicacao)}` : t('pages.livro.em_breve')}
              />
            )
          })}
        </div>
      </div>
    </section>
  )
}
